insert into property.screening_rules (id, jurisdiction_code, scope, locality, rule_key, title, topic, effects, effective_from, effective_to, status, enforcement, citation, source_url, legal_resource_id, verification, verified_on, notes, metadata) values
  ('41ad5506-3426-53a2-8b1e-11bdccfd1386', 'US', 'federal', null, 'fcra_adverse_action_notice', 'FCRA adverse-action notice and credit score disclosure', 'notices', '{"notices":{"extraContent":["adverse_action_notice","cra_did_not_make_decision","cra_name_address_phone","credit_score_disclosure_if_used","dispute_right","free_report_right_60_days"]}}'::jsonb, null, null, 'active', 'warn', '15 U.S.C. §1681m(a); §1681g(f)', 'https://www.law.cornell.edu/uscode/text/15/1681m', null, 'verified', '2026-11-08', 'The notice, the screening company''s contact details and the rights statement may be oral, written or electronic; only the credit score disclosure must be written or electronic, and only when a score was used. A conditional approval on worse terms can be adverse action. Read on the Cornell LII mirror (uscode.house.gov returned 404 during the check).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.law.cornell.edu/uscode/text/15/1681m","https://www.law.cornell.edu/uscode/text/15/1681g","https://www.law.cornell.edu/uscode/text/15/1681a"],"quotes":["If any person takes any adverse action with respect to any consumer that is based in whole or in part on any information contained in a consumer report, the person shall—","provide to the consumer written or electronic disclosure— (A) of a numerical credit score","a statement that the consumer reporting agency did not make the decision to take the adverse action"]}'::jsonb),
  ('af31b2a6-e167-5c7b-86b9-699cfa5e8728', 'US', 'federal', null, 'fcra_reporting_time_limits', 'FCRA limits on reporting old civil judgments and arrests', 'eviction', '{}'::jsonb, null, null, 'active', 'warn', '15 U.S.C. §1681c(a)(2), (a)(5), (b)', 'https://www.law.cornell.edu/uscode/text/15/1681c', null, 'verified', '2026-11-08', 'Limits what a screening company may report (seven years or the statute of limitations, whichever is longer), not what a landlord may weigh; convictions have no FCRA time limit. So it sets no look-back here. Read on the Cornell LII mirror (uscode.house.gov returned 404 during the check).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.law.cornell.edu/uscode/text/15/1681c"],"quotes":["Civil suits, civil judgments, and records of arrest that, from date of entry, antedate the report by more than seven years or until the governing statute of limitations has expired, whichever is the longer period"]}'::jsonb),
  ('cc4113bd-608a-59af-8169-56b654c9cc9a', 'US', 'federal', null, 'fcra_permissible_purpose', 'FCRA permissible purpose for tenant screening reports', 'process', '{}'::jsonb, null, null, 'active', 'warn', '15 U.S.C. §1681b(a)(3)(F)(i)', 'https://www.law.cornell.edu/uscode/text/15/1681b', null, 'verified', '2026-11-08', 'Informational. A rental application is a transaction the applicant starts; the statute doesn''t name landlords. Read on the Cornell LII mirror (uscode.house.gov returned 404 during the check).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.law.cornell.edu/uscode/text/15/1681b"],"quotes":["otherwise has a legitimate business need for the information— (i) in connection with a business transaction that is initiated by the consumer"]}'::jsonb),
  ('541d39d5-8126-5f7b-bab2-b9b30c5690c7', 'US', 'federal', null, 'fcra_disposal_rule', 'FTC Disposal Rule for consumer report information', 'process', '{}'::jsonb, '2005-06-01', null, 'active', 'warn', '16 CFR Part 682; 15 U.S.C. §1681w', 'https://www.ecfr.gov/current/title-16/chapter-I/subchapter-F/part-682', null, 'verified', '2026-11-08', 'Informational; governs disposing of screening reports (RISK-11). Sets no retention period. Read through the eCFR renderer API because the eCFR page redirected to a bot check.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.ecfr.gov/api/renderer/v1/content/enhanced/current/title-16?part=682","https://www.law.cornell.edu/uscode/text/15/1681w"],"quotes":["must properly dispose of such information by taking reasonable measures to protect against unauthorized access to or use of the information in connection with its disposal."]}'::jsonb),
  ('a0ce6652-dbaf-50c0-95c8-3a9e152ec820', 'US', 'federal', null, 'fair_housing_act_3604', 'Fair Housing Act: discrimination in renting', 'process', '{}'::jsonb, null, null, 'active', 'warn', '42 U.S.C. §3604 (exemptions §3603(b), §3607)', 'https://www.law.cornell.edu/uscode/text/42/3604', null, 'verified', '2026-11-08', 'Informational. Criminal history and source of income aren''t protected classes in the text; §3607(b)(4) allows action based on a conviction for illegal manufacture or distribution of a controlled substance. Screening policies can still violate the Act through their effect (24 CFR 100.500).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.law.cornell.edu/uscode/text/42/3604","https://www.law.cornell.edu/uscode/text/42/3607"],"quotes":["To discriminate against any person in the terms, conditions, or privileges of sale or rental of a dwelling"]}'::jsonb),
  ('8963d15c-e80e-57a7-b9b0-d775d6d819f8', 'US', 'federal', null, 'hud_discriminatory_effects_rule', 'HUD discriminatory-effects (disparate impact) standard', 'process', '{}'::jsonb, '2023-05-01', null, 'active', 'warn', '24 CFR 100.500', 'https://www.ecfr.gov/current/title-24/subtitle-B/chapter-I/subchapter-A/part-100/subpart-G/section-100.500', null, 'verified', '2026-11-08', 'Still in the CFR on 2026-11-08. HUD has proposed removing it: 91 FR 1475 (Jan 14, 2026, Docket FR-6540-P-01) and a supplemental proposal, 91 FR 51416 (Aug 10, 2026, FR-6540-P-02); no final rule as of the check. Disparate-impact liability under the Act itself (Inclusive Communities, 2015) is untouched. Mark repealed only when a final rule publishes.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.ecfr.gov/api/renderer/v1/content/enhanced/current/title-24?part=100&section=100.500","https://www.federalregister.gov/api/v1/documents/2026-00590.json","https://www.federalregister.gov/api/v1/documents/2026-16228.json"],"quotes":["Liability may be established under the Fair Housing Act based on a practice''s discriminatory effect, even if the practice was not motivated by a discriminatory intent."],"watch":"RIN 2529-AB09","pendingRepeal":true}'::jsonb),
  ('815a4ed8-cf6d-54bd-8bb3-e18d99e723a9', 'US', 'federal', null, 'hud_ogc_criminal_records_guidance', 'HUD guidance on criminal records under the Fair Housing Act (2016) and its 2022 implementation memo', 'criminal', '{}'::jsonb, '2016-04-04', null, 'withdrawn', 'warn', 'HUD OGC Guidance (Apr 4, 2016); FHEO memo (Jun 10, 2022); withdrawn, 91 FR 44867 and 91 FR 17291', 'https://www.federalregister.gov/documents/2026/07/17/2026-14432/withdrawal-of-guidance-documents', null, 'verified', '2026-11-08', 'Withdrawn: the 2016 guidance effective Sep 25, 2025 (FR 2026-14432) and the 2022 memo effective Sep 17, 2025 (FR 2026-06624). HUD''s letter of Nov 25, 2025 also rescinded PIH 2015-19 for assisted housing. Kept for reference only: it changes no outcome. The Fair Housing Act, 24 CFR 100.500 and state and local fair-chance laws still apply.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.federalregister.gov/documents/full_text/html/2026/07/17/2026-14432.html","https://www.federalregister.gov/documents/full_text/html/2026/04/06/2026-06624.html"],"quotes":["The withdrawal of the guidance was effective September 25, 2025.","Effective date of withdrawal: September 17, 2025.","should not be relied upon as authoritative."]}'::jsonb),
  ('d987e12a-4567-58bc-94e1-cbac756ea76b', 'US', 'federal', null, 'cfpb_name_only_matching_opinion', 'CFPB advisory opinion on name-only matching', 'process', '{}'::jsonb, '2021-11-10', null, 'withdrawn', 'warn', '86 FR 62468 (Nov 10, 2021); withdrawn, 90 FR 20084 (May 12, 2025)', 'https://www.federalregister.gov/documents/2025/05/12/2025-08286/interpretive-rules-policy-statements-and-advisory-opinions-withdrawal', null, 'verified', '2026-11-08', 'Withdrawn May 12, 2025. The screening company''s own FCRA accuracy duty (15 U.S.C. §1681e(b)) is unchanged. A Congressional Review Act resolution to overturn the withdrawal (S.J.Res.140) was not enacted per secondary trackers.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.federalregister.gov/api/v1/documents/2021-24471.json","https://www.federalregister.gov/documents/full_text/html/2025/05/12/2025-08286.html"],"quotes":["11. Fair Credit Reporting; Name-Only Matching Procedures, 86 FR 62468 (Nov. 10, 2021).","The withdrawals are applicable as of May 12, 2025."]}'::jsonb),
  ('1bbd9019-c340-541b-883f-36c27016918b', 'US', 'federal', null, 'vawa_housing_protections', 'VAWA protections in HUD-covered housing', 'process', '{}'::jsonb, '2016-12-16', null, 'active', 'warn', '24 CFR 5.2005; 34 U.S.C. §12491', 'https://www.ecfr.gov/current/title-24/subtitle-A/part-5/subpart-L/section-5.2005', null, 'verified', '2026-11-08', 'Applies only to covered housing programs (Section 8, public housing, HOME, LIHTC and others listed in 24 CFR 5.2003); see the affordable-housing module. Covered providers must give applicants the notice of occupancy rights and certification form.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.ecfr.gov/api/renderer/v1/content/enhanced/current/title-24?part=5&section=5.2005","https://www.law.cornell.edu/uscode/text/34/12491"],"quotes":["may not be denied admission to, denied assistance under, terminated from participation in, or evicted from the housing on the basis or as a direct result of the fact that the applicant or tenant is or has been a victim of domestic violence"]}'::jsonb),
  ('dbd17c8f-e618-5190-b321-fe7c543cb798', 'US-NY-NYC', 'city', 'New York City', 'nyc_fair_chance_housing_act', 'NYC Fair Chance for Housing Act', 'criminal', '{"criminal":{"timing":"after_conditional_offer","lookbackYears":{"misdemeanor":3,"felony":5},"excluded":["adjournment_in_contemplation_of_dismissal","dismissed","infractions","juvenile","pending_cases","sealed_expunged"],"individualizedAssessment":true,"responseDays":5,"mustAttachDocs":true},"preOfferInquiryBanned":["criminal"],"process":{"writtenDenialRequired":true},"notices":{"extraContent":["written_reason_with_supporting_documents"]}}'::jsonb, '2025-01-01', null, 'active', 'warn', 'NYC Admin. Code §8-107(5)(o), §8-102a (Local Law 24 of 2024)', 'https://www.nyc.gov/assets/cchr/downloads/pdf/amendments/Local-Law-24.pdf', null, 'verified', '2026-11-08', 'Two-step: the check runs only after a conditional offer (a lease committing the unit). Look-backs run from release from incarceration, or from sentencing when there was none. Response window is five business days. Sex-offense registry convictions are reviewable without a time limit. Exempt: owner-occupied buildings of up to two families and rooms in an owner-occupied unit (not publicly assisted housing). Yields where federal or state law requires a check. Text read from the Commission on Human Rights'' copy of LL 24 (amlegal returned 403).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.nyc.gov/assets/cchr/downloads/pdf/amendments/Local-Law-24.pdf"],"quotes":["shall not conduct such criminal background check until such covered entity has taken the following actions","where less than three years have passed from (a) the date of release from incarceration, or (b) the date of sentencing","Any other felony conviction under the laws of New York or another jurisdiction where less than five years have passed","no later than five business days following the receipt of such information","Provide such individual with a written copy of the reason for the adverse action, including: (i) A copy of supporting documents that were reviewed"]}'::jsonb),
  ('5b32465d-855e-5022-b0fc-59c95bf67e04', 'US-IL-COOK', 'county', 'Cook County', 'cook_county_just_housing_amendment', 'Cook County Just Housing Amendment', 'criminal', '{"criminal":{"timing":"after_prequalification","lookbackYears":{"misdemeanor":3,"felony":3},"individualizedAssessment":true,"responseDays":5,"mustAttachDocs":true},"preOfferInquiryBanned":["criminal"],"process":{"criteriaDisclosureBeforeFee":true,"writtenDenialRequired":true}}'::jsonb, '2019-12-31', null, 'active', 'warn', 'Cook County Code §42-38 (Ord. 19-2394); Commission on Human Rights Procedural Rules Part 700', 'https://www.cookcountyil.gov/sites/g/files/ywwepo161/files/documents/2024-11/Human%20Rights%20Procedural%20Rules_11202024%20Approved_0.pdf', null, 'checked', '2026-11-08', 'Two-step: criminal history only after the applicant pre-qualifies on every other criterion (no unit hold is required, §770.100). Tenant-selection criteria are disclosed before a fee (§730.100) and denials are written (§760.110). Denial needs a demonstrable-risk individualized assessment (none needed for current sex-offender registration). Exempt: rooms in an owner-occupied home. Whether it applies inside Chicago and other home-rule municipalities is unverified: the County''s guide says its ordinances may not apply where a municipality has its own law, and Chicago has no fair-chance housing ordinance. Applied to Chicago properties here pending confirmation; ask counsel. Enforcement began Feb 1, 2020.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://webapi.legistar.com/v1/cook-county/matters?$filter=MatterFile eq ''19-2394''","https://www.cookcountyil.gov/sites/g/files/ywwepo161/files/documents/2024-11/Human%20Rights%20Procedural%20Rules_11202024%20Approved_0.pdf"],"quotes":["before the prequalification process is complete, and the housing provider has determined the applicant has satisfied all other application criteria","prohibited from basing any adverse housing decision, in whole or in part, upon a conviction that occurred more than (3) years from the date of the housing application","Within five days of obtaining a background check on an applicant, the housing provider must deliver a copy of the background check to the applicant.","the applicant shall have an additional five (5) business days to produce evidence"]}'::jsonb),
  ('37978a78-a6e9-530b-ad10-84e2e164edb9', 'US-NJ', 'state', null, 'nj_fair_chance_in_housing_act', 'New Jersey Fair Chance in Housing Act', 'criminal', '{"criminal":{"timing":"after_conditional_offer","individualizedAssessment":true,"responseDays":10},"preOfferInquiryBanned":["criminal"],"process":{"writtenDenialRequired":true}}'::jsonb, '2022-01-01', null, 'active', 'warn', 'N.J.S.A. 46:8-52 to -64; N.J.A.C. 13:5', 'https://www.njoag.gov/wp-content/uploads/2021/12/Fair-Chance-in-Housing-Act_NJSA-46-8-52-et-seq.pdf', null, 'verified', '2026-11-08', 'Look-backs are tiered by offense degree, counted to the conditional offer from conviction or release: first degree 6 years, second and third degree 4 years, fourth degree 1 year; some offenses (murder, aggravated sexual assault, lifetime registration and others) have no limit. Not encoded as one number, so set your criteria with counsel. Records go to the applicant on request within 30 days. Exempt: owner-occupied premises of four or fewer units. Text read from the Division on Civil Rights'' copies (njleg refused the connection).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.njoag.gov/wp-content/uploads/2021/12/Fair-Chance-in-Housing-Act_NJSA-46-8-52-et-seq.pdf","https://www.njoag.gov/wp-content/uploads/2022/02/Fair-Chance-in-Housing-Act-Regulations.pdf"],"quotes":["A housing provider shall not make any oral or written inquiry regarding an applicant''s criminal record prior to making a conditional offer.","the right to dispute, within 10 days of receiving such statement, the relevance and accuracy of the criminal record"]}'::jsonb),
  ('c82aca3f-a0b3-5839-9ece-e51304f4bdec', 'US-DC', 'state', 'District of Columbia', 'dc_fair_criminal_record_screening', 'DC Fair Criminal Record Screening for Housing Act', 'criminal', '{"criminal":{"timing":"after_conditional_offer","individualizedAssessment":true},"preOfferInquiryBanned":["criminal"],"process":{"criteriaDisclosureBeforeFee":true,"writtenDenialRequired":true}}'::jsonb, '2017-07-20', null, 'active', 'warn', 'D.C. Code §§42-3541.01 to .09', 'https://code.dccouncil.gov/us/dc/council/code/sections/42-3541.02', null, 'verified', '2026-11-08', 'Only a closed list of about 48 offenses within the past seven years may be considered, and nothing else, so no general look-back is encoded; set criminal criteria with counsel. Eligibility criteria are disclosed before an application fee. The applicant may ask within 20 days of a withdrawal for a copy of the information relied on. Exempt: owner-occupied housing with three or fewer rental units. No 2022 amendment to criminal screening was found; the 2022 Fairness in Renting Act covers eviction records and fees.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://code.dccouncil.gov/us/dc/council/code/sections/42-3541.01","https://code.dccouncil.gov/us/dc/council/code/sections/42-3541.02","https://code.dccouncil.gov/us/dc/council/code/sections/42-3541.03"],"quotes":["Before making a conditional offer, a housing provider may not make an inquiry about or require an applicant to disclose or reveal a pending criminal accusation or criminal conviction.","may only consider a pending criminal accusation or criminal conviction that has occurred within the past 7 years when the pending criminal accusation or criminal conviction is for one or more of the following crimes"]}'::jsonb),
  ('18d54588-3bfe-5ae5-9c52-980424107fb9', 'US-MN-MINNEAPOLIS', 'city', 'Minneapolis', 'minneapolis_applicant_screening', 'Minneapolis applicant screening criteria', 'process', '{"process":{"criteriaDisclosureBeforeFee":true,"writtenDenialRequired":true}}'::jsonb, '2020-06-01', null, 'active', 'warn', 'Minneapolis Code of Ordinances §244.2030', 'https://www.minneapolismn.gov/media/-www-content-assets/documents/Renter-Protections-Owners-Guide---English.pdf', null, 'checked', '2026-11-08', 'Criteria must be published before accepting applications. Landlords choose either the inclusive screening criteria (misdemeanors over 3 years and most felonies over 7 years from sentencing not used; settled evictions over 1 year and judgments 3 or more years old not used; no denial on credit score alone) or an individualized assessment of supplemental evidence. Because it''s a choice, those limits aren''t encoded. Written denial within 14 days. Effective June 1, 2020 for owners of 16+ units and Dec 1, 2020 for the rest. An 8th Circuit appeal of the denied injunction failed (2022). Ord. 2026-007 (Apr 23, 2026) also bars asking about immigration status. Code text read from a mirror of the certified Ord. 2026-007 (municode and LIMS were blocked); the city''s owner guide linked here predates it.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://civicmeetings-twincities.pages.dev/meetings/minneapolis/5954-city-council-2026-04-23/attachments/43870-2026-007.pdf","https://www.minneapolismn.gov/media/-www-content-assets/documents/Renter-Protections-Owners-Guide---English.pdf"],"quotes":["Any conviction for misdemeanor offenses for which the dates of sentencing are older than three (3) years;","a landlord must accept and consider all supplemental evidence provided with a completed application"]}'::jsonb),
  ('31daca46-491a-55d3-b874-af3b6c9d4d94', 'US-CA', 'state', null, 'ca_source_of_income', 'California source-of-income protection, voucher income test and credit alternative', 'source_of_income', '{"income":{"tenantPortionForVoucher":true},"sourceOfIncome":{"protected":true,"includesVouchers":true},"credit":{"voucherHolderLimits":true}}'::jsonb, '2020-01-01', null, 'active', 'warn', 'Cal. Gov. Code §12955(a), (o), (p); §12927(i)', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=GOV&sectionNum=12955', null, 'verified', '2026-11-08', 'With a government rent subsidy, income standards must use the tenant''s share of the rent, and a credit check must come with the option to give alternative evidence of ability to pay (from Jan 1, 2024). Asking about the level or source of income isn''t by itself discrimination. Read on the california.public.law mirror (leginfo returned 403).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://california.public.law/codes/ca_gov''t_code_section_12955","https://california.public.law/codes/ca_gov''t_code_section_12927"],"quotes":["including, but not limited to, federal housing assistance vouchers issued under Section 8 of the United States Housing Act of 1937","Use a financial or income standard in assessing eligibility for the rental of housing that is not based on the portion of the rent to be paid by the tenant.","Use a person''s credit history as part of the application process ... without offering the applicant the option ... of providing lawful, verifiable alternative evidence of the applicant''s reasonable ability to pay"]}'::jsonb),
  ('c20dff35-79f6-56b3-9412-e84bcdc0a68f', 'US-NY', 'state', null, 'ny_lawful_source_of_income', 'New York lawful source of income protection', 'source_of_income', '{"sourceOfIncome":{"protected":true,"includesVouchers":true}}'::jsonb, '2019-04-12', null, 'active', 'warn', 'N.Y. Exec. Law §296(5)(a)(1); §292(36)', 'https://www.nysenate.gov/legislation/laws/EXC/296', null, 'verified', '2026-11-08', 'Statewide. Exemptions include owner-occupied two-family homes and owner-occupied rooming houses (per the Division of Human Rights; exemption text not re-quoted). The effective date is from the Division''s brochure.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.nysenate.gov/legislation/laws/EXC/296","https://www.nysenate.gov/legislation/laws/EXC/292"],"quotes":["any form of federal, state, or local public assistance or housing assistance including, but not limited to, section 8 vouchers"]}'::jsonb),
  ('f1278c12-e079-551e-9568-969c50cf8a1a', 'US-NJ', 'state', null, 'nj_source_of_lawful_income', 'New Jersey source of lawful income protection and tenant-share income test', 'source_of_income', '{"income":{"tenantPortionForVoucher":true},"sourceOfIncome":{"protected":true,"includesVouchers":true}}'::jsonb, null, null, 'active', 'warn', 'N.J.S.A. 10:5-12(g)(4), (h)(4); 10:5-5 (P.L.2025, c.251)', 'https://pub.njleg.gov/bills/2024/PL25/251_.HTM', null, 'checked', '2026-11-08', 'An independent re-check couldn''t reach the official text (connection refused): re-verify. The tenant-share rule and the expanded definition took effect Jan 12, 2026 (P.L.2025, c.251); the protection itself is older. Read through a Wayback copy of the official chapter-law page (pub.njleg.gov refused the connection).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://web.archive.org/web/2026/https://pub.njleg.gov/bills/2024/PL25/251_.HTM","https://www.njoag.gov/wp-content/uploads/2021/06/fact_SOI.pdf"],"quotes":["any federal, State, or local public assistance or housing assistance voucher or funds, including Section 8 housing choice vouchers","any minimum income requirement or financial standard that is not based exclusively on the portion of the rent to be paid by the tenant"]}'::jsonb),
  ('b2226631-3cc1-5727-abfb-62467e9adf7d', 'US-WA', 'state', null, 'wa_source_of_income', 'Washington source-of-income protection and voucher income test', 'source_of_income', '{"income":{"tenantPortionForVoucher":true},"sourceOfIncome":{"protected":true,"includesVouchers":true}}'::jsonb, '2018-09-30', null, 'active', 'warn', 'RCW 59.18.255', 'https://app.leg.wa.gov/RCW/default.aspx?cite=59.18.255', null, 'verified', '2026-11-08', 'Section 8 isn''t named; housing assistance and rent vouchers or subsidies cover it. Narrow exception where an inspection-repair estimate exceeds $1,500 and no landlord mitigation funds were received.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://app.leg.wa.gov/RCW/default.aspx?cite=59.18.255"],"quotes":["''Source of income'' includes benefits or subsidy programs including housing assistance, public assistance, emergency rental assistance","any source of income in the form of a rent voucher or subsidy must be subtracted from the total of the monthly rent prior to calculating if the income criteria have been met."]}'::jsonb),
  ('efb025fb-15df-5b86-8abe-6c6f3e30c519', 'US-OR', 'state', null, 'or_source_of_income', 'Oregon source-of-income protection (including Section 8)', 'source_of_income', '{"sourceOfIncome":{"protected":true,"includesVouchers":true}}'::jsonb, null, null, 'active', 'warn', 'ORS 659A.421(1)(d), (2)(a)', 'https://oregon.public.law/statutes/ors_659A.421', null, 'verified', '2026-11-08', 'Ability to pay must take the value of housing assistance into account; the statute doesn''t say tenant''s share only, so that isn''t encoded (Portland''s ordinance does require it). Read on the oregon.public.law mirror (oregonlegislature.gov refused the connection).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://oregon.public.law/statutes/ors_659A.421"],"quotes":["''Source of income'' includes federal rent subsidy payments under 42 U.S.C. 1437f and any other local, state or federal housing assistance","taking into account the value of the prospective renter''s or prospective lessee''s local, state and federal housing assistance"]}'::jsonb),
  ('7fdc3ca2-0f8b-571a-a5bb-3549e2b6a9e0', 'US-IL', 'state', null, 'il_source_of_income', 'Illinois source-of-income protection in housing', 'source_of_income', '{"sourceOfIncome":{"protected":true}}'::jsonb, '2023-01-01', null, 'active', 'warn', '775 ILCS 5/1-103(O-5); 5/3-102', 'https://www.ilga.gov/legislation/ilcs/fulltext.asp?DocName=077500050K1-103', null, 'checked', '2026-11-08', 'An independent re-check couldn''t reach the official text (connection refused): re-verify. Vouchers aren''t named in the statute; the Governor''s office describes the law as covering Section 8 vouchers (secondary), so that isn''t encoded. The Act also lists arrest record as a protected basis. Read through Wayback copies of the official ILGA pages (ilga.gov refused the connection).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://web.archive.org/web/20250608/https://www.ilga.gov/legislation/ilcs/fulltext.asp?DocName=077500050K1-103","https://web.archive.org/web/20250523/https://www.ilga.gov/legislation/ilcs/fulltext.asp?DocName=077500050K3-102"],"quotes":["''Source of income'' means the lawful manner by which an individual supports himself or herself and his or her dependents.","because of unlawful discrimination, familial status, immigration status, source of income, or an arrest record"]}'::jsonb),
  ('f8403218-1546-5aba-8035-97ad72289e09', 'US-MA', 'state', null, 'ma_housing_subsidy_protection', 'Massachusetts protection for public assistance and housing subsidy recipients', 'source_of_income', '{"sourceOfIncome":{"protected":true,"includesVouchers":true}}'::jsonb, null, null, 'active', 'warn', 'M.G.L. c.151B §4(10)', 'https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter151B/Section4', null, 'checked', '2026-11-08', 'An independent re-check couldn''t reach the official text (connection refused): re-verify. Section 8 isn''t named; housing subsidies and rental assistance cover it, including the program''s requirements. Read through a Wayback copy of the official page.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://web.archive.org/web/20260919/https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXI/Chapter151B/Section4"],"quotes":["who is a tenant receiving federal, state, or local housing subsidies, including rental assistance or rental supplements, because the individual is such a recipient, or because of any requirement of such public assistance, rental assistance, or housing subsidy program."]}'::jsonb),
  ('dbc663ac-4d0a-5722-a92a-8f66b3929f59', 'US-DC', 'state', 'District of Columbia', 'dc_source_of_income', 'DC source-of-income protection and limits on screening subsidy holders', 'source_of_income', '{"sourceOfIncome":{"protected":true,"includesVouchers":true},"credit":{"voucherHolderLimits":true}}'::jsonb, null, null, 'active', 'warn', 'D.C. Code §2-1402.21(a), (e), (g); §2-1401.02(29)', 'https://code.dccouncil.gov/us/dc/council/code/sections/2-1402.21', null, 'verified', '2026-11-08', 'For applicants with an income-based housing subsidy, income level, credit score and credit issues from unsubsidized periods may not be considered (from May 18, 2022), which goes beyond a tenant-share test; no field captures that, so read the rule. Extra fees, deposits or rent for subsidy holders are presumed discriminatory.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://code.dccouncil.gov/us/dc/council/code/sections/2-1402.21","https://code.dccouncil.gov/us/dc/council/code/sections/2-1401.02"],"quotes":["The monetary assistance provided to an owner of a housing accommodation under section 8 ... shall be considered a source of income under this section.","Income level (other than whether or not the level is below a threshold as required by local or federal law), a credit score, or the lack of credit score"]}'::jsonb),
  ('529626f8-afbb-5a84-b114-d8347b62c09c', 'US-CO', 'state', null, 'co_source_of_income', 'Colorado source-of-income protection', 'source_of_income', '{"sourceOfIncome":{"protected":true,"includesVouchers":true}}'::jsonb, '2021-01-01', null, 'active', 'warn', 'C.R.S. 24-34-501(4.5); 24-34-502(1)(l)-(p) (HB20-1332)', 'https://leg.colorado.gov/bills/hb20-1332', null, 'verified', '2026-11-08', 'Landlords with three or fewer units are exempt from these provisions; an owner of five or fewer single-family homes need not accept federal vouchers for them. Credit checks are allowed if every applicant is checked. Read from the signed act (the codified text is hosted by Lexis).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://leg.colorado.gov/bill_files/58498/download","https://leg.colorado.gov/bills/hb20-1332"],"quotes":["INCOME OR RENTAL PAYMENTS DERIVED FROM ANY GOVERNMENT OR PRIVATE ASSISTANCE, GRANT, OR LOAN PROGRAM."]}'::jsonb),
  ('5fd67456-1fa2-5237-8551-fe87e4b10843', 'US-CO', 'state', null, 'co_rental_application_income_credit_limits', 'Colorado income cap and limits on screening subsidy holders', 'income', '{"income":{"maxMultiple":2,"tenantPortionForVoucher":true},"credit":{"voucherHolderLimits":true}}'::jsonb, '2023-08-07', null, 'active', 'warn', 'C.R.S. 38-12-904(1)(c)-(e) (SB23-184)', 'https://leg.colorado.gov/laws/session-laws/SB23-184/402/download', null, 'verified', '2026-11-08', 'Income may not be required above 2× the rent for any applicant; for subsidy users only income against 2× their share may be checked, and credit scores or events may not be considered unless federal law requires. Exception where a funder requires income-qualifying for income-restricted units.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://leg.colorado.gov/laws/session-laws/SB23-184/402/download"],"quotes":["A LANDLORD SHALL NOT REQUIRE A PROSPECTIVE TENANT TO HAVE AN ANNUAL AMOUNT OF INCOME THAT EXCEEDS TWO HUNDRED PERCENT OF THE ANNUAL COST OF RENT.","EQUALS OR EXCEEDS TWO HUNDRED PERCENT OF THE PORTION OF THE ANNUAL COST OF RENT THAT IS TO BE PAID BY THE PROSPECTIVE TENANT","CREDIT SCORE, ADVERSE CREDIT EVENT, OR LACK OF CREDIT SCORE UNLESS THE LANDLORD IS REQUIRED BY FEDERAL LAW"]}'::jsonb),
  ('1ef7b20c-0b06-59c7-af03-488f57aef368', 'US-VA', 'state', null, 'va_source_of_funds', 'Virginia source-of-funds protection', 'source_of_income', '{"sourceOfIncome":{"protected":true,"includesVouchers":true}}'::jsonb, '2020-07-01', null, 'active', 'warn', 'Va. Code §36-96.1:1; §36-96.3(A)(1); §36-96.2(I), (J)', 'https://law.lis.virginia.gov/vacode/title36/chapter5.1/section36-96.3/', null, 'verified', '2026-11-08', 'Vouchers are covered as a subsidy program. Exempt: owners of four or fewer rental units (unless they hold over 10% of more than four). A landlord may decline if the source isn''t approved within 15 days of the request for tenancy approval.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://law.lis.virginia.gov/vacode/title36/chapter5.1/section36-96.1:1/","https://law.lis.virginia.gov/vacode/title36/chapter5.1/section36-96.3/","https://law.lis.virginia.gov/vacode/title36/chapter5.1/section36-96.2/"],"quotes":["any source that lawfully provides funds to or on behalf of a renter or buyer of housing, including any assistance, benefit, or subsidy program"]}'::jsonb),
  ('0fec4eed-ac18-5414-80bb-05b70eed1a48', 'US-MN', 'state', null, 'mn_public_assistance_status', 'Minnesota protection for public assistance status', 'source_of_income', '{"sourceOfIncome":{"protected":true}}'::jsonb, null, null, 'active', 'warn', 'Minn. Stat. §363A.09 subd. 1; §363A.03 subd. 47', 'https://www.revisor.mn.gov/statutes/cite/363A.03', null, 'verified', '2026-11-08', 'Covers tenants receiving rental assistance or rent supplements; housing choice vouchers aren''t named, so voucher coverage isn''t encoded. Minnesota courts have let landlords decline Section 8 participation (secondary sources). Bills to add a voucher protection (HF 2021, 2025) weren''t enacted in the 2026 statutes. Minneapolis has its own ordinance.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.revisor.mn.gov/statutes/cite/363A.09","https://www.revisor.mn.gov/statutes/cite/363A.03"],"quotes":["''Status with regard to public assistance'' means the condition of being a recipient of federal, state, or local assistance, including medical assistance, or of being a tenant receiving federal, state, or local subsidies, including rental assistance or rent supplements."]}'::jsonb),
  ('27967ff2-1d2d-5d4d-886a-792743a16a09', 'US-CA', 'state', null, 'ca_application_screening_fee', 'California application screening fee limits', 'fees', '{"fees":{"capType":"cpi","cap":68.96,"actualCostLimit":true,"receiptRequired":true,"refundIfNotScreened":true,"noFeeIfNoUnit":true,"portableReport":"may"}}'::jsonb, '2025-01-01', null, 'active', 'warn', 'Cal. Civ. Code §1950.6 (as amended by AB 2493, Stats. 2024, ch. 966)', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=CIV&sectionNum=1950.6', null, 'checked', '2026-11-08', 'The statute caps the fee at actual cost and at $30, adjustable each year by the CPI since Jan 1, 1998; the state publishes no adjusted figure. The $68.96 cap encoded here is the Berkeley Rent Board''s published 2026 maximum, which Berkeley ties to §1950.6(b); confirm it yearly. Itemized receipt; copy of the credit report within 7 days; a fee only if the landlord either takes applications in order and approves the first who meets written criteria, or refunds non-selected applicants within 7 days of selecting a tenant or 30 days after they applied, whichever is first. Unused fee amounts (no screening done) go back with no set deadline. Statute read on two mirrors (leginfo returned 403).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://california.public.law/codes/civil_code_section_1950.6","https://codes.findlaw.com/ca/civil-code/civ-sect-1950-6/","https://rentboard.berkeleyca.gov/laws-regulations/city-berkeley-ordinances-affecting-rental-properties/tenant-screening-and"],"quotes":["not be greater than thirty dollars ($30) per applicant","may be adjusted annually by the landlord or their agent commensurate with an increase in the Consumer Price Index","they know or should have known that no rental unit is available","The maximum tenant screening fee for 2026 is $68.96."],"capSource":"Berkeley Rent Board, 2026","capYear":2026}'::jsonb),
  ('942c00f4-1994-58f6-bcb6-3e4681331cca', 'US-NY', 'state', null, 'ny_background_check_fee', 'New York application fee ban and $20 background check fee', 'fees', '{"fees":{"capType":"fixed","cap":20,"actualCostLimit":true,"receiptRequired":true},"notices":{"extraContent":["copy_of_background_or_credit_check"]}}'::jsonb, '2019-06-14', null, 'active', 'warn', 'N.Y. Real Prop. Law §238-a(1)(a)-(b)', 'https://www.nysenate.gov/legislation/laws/RPP/238-A', null, 'verified', '2026-11-08', 'No application fee; a background or credit check fee of actual cost or $20, whichever is less, with a copy of the check and the receipt or invoice. Waived if the applicant brings a check from the past 30 days. Co-ops and some senior housing differ. Effective date from the State Bar (secondary).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.nysenate.gov/legislation/laws/RPP/238-A"],"quotes":["no landlord, lessor, sub-lessor or grantor may demand any payment, fee, or charge for the processing, review or acceptance of an application","no more than the actual cost of the background check and credit check or twenty dollars, whichever is less","shall waive the fee or fees if the potential tenant provides a copy of a background check or credit check conducted within the past thirty days"]}'::jsonb),
  ('5ce7d96c-6f8c-54ae-9cfb-67b95cf466c9', 'US-NY', 'state', null, 'ny_no_denial_for_housing_court_history', 'New York ban on refusing to rent over landlord-tenant court history', 'eviction', '{"eviction":{"allowed":false}}'::jsonb, null, null, 'active', 'warn', 'N.Y. Real Prop. Law §227-f', 'https://www.nysenate.gov/legislation/laws/RPP/227-F', null, 'verified', '2026-11-08', 'A landlord who checks a tenant screening bureau or court records and then refuses to rent is presumed to have violated it. The Attorney General enforces ($500–$1,000 per violation). Effective July 14, 2019 (secondary).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.nysenate.gov/legislation/laws/RPP/227-F"],"quotes":["No landlord of a residential premises shall refuse to rent or offer a lease","involved in a past or pending landlord-tenant action","There shall be a rebuttable presumption that a person is in violation of this section"]}'::jsonb),
  ('1c3f6267-3301-5a78-afeb-361d8f2d01b9', 'US-WA', 'state', null, 'wa_screening_notice_and_fee', 'Washington screening notice, fee limit and adverse-action notice', 'fees', '{"fees":{"capType":"actual_cost","actualCostLimit":true,"portableReport":"may"},"process":{"criteriaDisclosureBeforeFee":true,"writtenDenialRequired":true},"notices":{"extraContent":["cra_name_address_and_rights","denial_criteria","reusable_report_acceptance_statement","types_of_information_accessed"]}}'::jsonb, null, null, 'active', 'warn', 'RCW 59.18.257', 'https://app.leg.wa.gov/RCW/default.aspx?cite=59.18.257', null, 'verified', '2026-11-08', 'Before collecting information: the types of information checked, criteria that may lead to denial, the screening company''s name and address with the applicant''s rights, and whether a comprehensive reusable report is accepted. Fees only for the screening report actually obtained, at no more than customary local cost. Liability up to $100 plus costs.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://app.leg.wa.gov/RCW/default.aspx?cite=59.18.257"],"quotes":["Prior to obtaining any information about a prospective tenant, the prospective landlord shall first notify","The amount charged may not exceed the customary costs charged by a screening service in the general area.","shall provide a written notice of the adverse action to the prospective tenant that states the reasons"]}'::jsonb),
  ('3dc79d89-2213-547e-ac0b-fad4bb1f91e8', 'US-CO', 'state', null, 'co_application_fee_portable_report', 'Colorado application fee limits and portable screening reports', 'fees', '{"fees":{"capType":"actual_cost","actualCostLimit":true,"receiptRequired":true,"refundIfNotScreened":true,"refundDays":20,"portableReport":"must"},"process":{"writtenDenialRequired":true},"notices":{"extraContent":["portable_report_right_advisement"]}}'::jsonb, '2019-08-02', null, 'active', 'warn', 'C.R.S. 38-12-903; 38-12-904(1.5), (2) (HB19-1106, HB23-1099, HB25-1236)', 'https://colorado.public.law/statutes/crs_38-12-903', null, 'verified', '2026-11-08', 'The fee covers only processing costs and is the same for every applicant; unused amounts go back within 20 days. A portable report no more than 30 days old must be accepted, with no fee charged. Written denial within 20 days with a copy of the report and dispute rights. From Jan 1, 2026 (HB25-1236) reports for subsidy users need not include credit history. Rental and credit history beyond seven years may not be considered (38-12-904(1)(a), not encoded).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://colorado.public.law/statutes/crs_38-12-903","https://colorado.public.law/statutes/crs_38-12-904","https://leg.colorado.gov/laws/session-laws/HB25-1236/399/download"],"quotes":["uses the entire amount of the fee to cover the landlord''s costs in processing the rental application","make a good-faith effort to remit such amount within twenty calendar days after processing the application.","a landlord shall accept a portable tenant screening report from a prospective tenant.","shall provide to the prospective tenant a written notice of the denial"]}'::jsonb),
  ('faedac51-a502-5b49-8fad-11390e3ace11', 'US-CO', 'state', null, 'co_rental_application_disclosures_2027', 'Colorado screening disclosures in rental applications (from 2027)', 'notices', '{"notices":{"extraContent":["general_evaluation_factors","information_landlord_will_access","third_party_screening_service_name"]}}'::jsonb, '2027-01-01', null, 'pending', 'warn', 'C.R.S. 38-12-904(1.7) (HB26-1196)', 'https://leg.colorado.gov/laws/session-laws/HB26-1196/326/download', null, 'verified', '2026-11-08', 'Signed June 2, 2026; in force Jan 1, 2027. Switch to active once in force.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://leg.colorado.gov/laws/session-laws/HB26-1196/326/download"],"quotes":["A LANDLORD SHALL INCLUDE IN ALL RENTAL APPLICATIONS:","NOTHING IN THIS SUBSECTION (1.7) REQUIRES A LANDLORD TO ADOPT OR DISCLOSE FIXED DISQUALIFYING CRITERIA."]}'::jsonb),
  ('c84bbdf8-63a5-5eec-b545-9c91f2f4ec2e', 'US-MA', 'state', null, 'ma_upfront_payment_limits', 'Massachusetts limits on payments before a tenancy (no application fee)', 'fees', '{"fees":{"capType":"banned"}}'::jsonb, null, null, 'active', 'warn', 'M.G.L. c.186 §15B(1)(b)', 'https://malegislature.gov/Laws/GeneralLaws/PartII/TitleI/Chapter186/Section15B', null, 'checked', '2026-11-08', 'Only first and last month''s rent, a security deposit and a lock and key may be required, so an application fee isn''t allowed. The official site refused the connection; the text was read on a third-party transcription. A 2025 budget amendment (broker fees) reportedly changed this section: re-check the official text.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://masslaw.neocities.org/18615B.html"],"quotes":["At or prior to the commencement of any tenancy, no lessor may require a tenant or prospective tenant ... to pay any amount in excess of the following:"]}'::jsonb),
  ('c3d6cf3a-5c47-5ca7-b040-309aa933a3df', 'US-VT', 'state', null, 'vt_application_fee_ban', 'Vermont ban on rental application fees', 'fees', '{"fees":{"capType":"banned"}}'::jsonb, null, null, 'active', 'warn', '9 V.S.A. §4456a(a)', 'https://legislature.vermont.gov/statutes/section/09/137/04456a', null, 'checked', '2026-11-08', 'Read on the FindLaw mirror (current to Jan 1, 2024; the official site refused the connection). Whether separate background or credit check fees are covered is disputed; the state''s Office of Economic Opportunity says they are (secondary). Bills to allow actual-cost check fees died in 2026.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://codes.findlaw.com/vt/title-9-commerce-and-trade/vt-st-tit-9-sect-4456a/"],"quotes":["A landlord or a landlord''s agent shall not charge an application fee to any individual in order to apply to enter into a rental agreement for a residential dwelling unit."]}'::jsonb),
  ('4e235c7d-8385-53c1-b2b5-d18e128d917f', 'US-VA', 'state', null, 'va_application_fee_cap', 'Virginia application fee cap', 'fees', '{"fees":{"capType":"fixed","cap":50}}'::jsonb, null, null, 'active', 'warn', 'Va. Code §55.1-1203', 'https://law.lis.virginia.gov/vacode/title55.1/chapter12/section55.1-1203/', null, 'verified', '2026-11-08', 'The $50 cap excludes actual out-of-pocket costs such as third-party screening, which may be added ($32 for public housing and HUD-assisted units). A refundable application deposit is separate and returned within 20 days less actual expenses. This version runs until July 1, 2027.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://law.lis.virginia.gov/vacode/title55.1/chapter12/section55.1-1203/"],"quotes":["An application fee shall not exceed $50, exclusive of any actual out-of-pocket expenses","shall refund to the applicant within 20 days after the applicant''s failure to rent the unit"]}'::jsonb),
  ('8f56cf66-4e7b-529d-bf87-6810e9b35fb8', 'US-VA', 'state', null, 'va_screening_disclosure_2027', 'Virginia fee and criteria disclosure before an application (from July 2027)', 'process', '{"process":{"criteriaDisclosureBeforeFee":true},"notices":{"extraContent":["automatic_denial_criteria","fee_and_deposit_amounts_and_refundability","tenant_selection_criteria"]}}'::jsonb, '2027-07-01', null, 'pending', 'warn', 'Va. Code §55.1-1203(A) (2026 c.1050)', 'https://law.lis.virginia.gov/vacode/title55.1/chapter12/section55.1-1203/', null, 'verified', '2026-11-08', 'Takes effect July 1, 2027. Switch to active once in force.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://law.lis.virginia.gov/vacode/title55.1/chapter12/section55.1-1203/"],"quotes":["the tenant selection criteria applicable to the unit","any criteria that will result in an automatic denial of the application"]}'::jsonb),
  ('bfbe070e-dc07-5410-9f64-7574e6c153ac', 'US-MN', 'state', null, 'mn_applicant_screening_fee', 'Minnesota applicant screening fee rules and eviction-record limits', 'fees', '{"eviction":{"excludeDismissed":true,"excludeSealed":true},"fees":{"refundIfNotScreened":true,"noFeeIfNoUnit":true},"process":{"criteriaDisclosureBeforeFee":true}}'::jsonb, null, null, 'active', 'warn', 'Minn. Stat. §504B.173', 'https://www.revisor.mn.gov/statutes/cite/504B.173', null, 'verified', '2026-11-08', 'No dollar cap. Disclose the screening company and the criteria in writing before taking the fee; receipt on request; the fee can''t be cashed until earlier applicants are screened; refund if rejected for an undisclosed reason or if an earlier applicant takes the unit. From Jan 1, 2025, no denial over a pending eviction, an expunged or non-public case, or one that didn''t end in a writ of recovery.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.revisor.mn.gov/statutes/cite/504B.173"],"quotes":["disclose in writing prior to accepting the applicant screening fee:","must return any amount of the applicant screening fee that is not used for those purposes.","No landlord may deny a rental application based on any of the following:"]}'::jsonb),
  ('ca4282ba-eb3d-5d91-b69d-1d897c72a949', 'US-DC', 'state', 'District of Columbia', 'dc_fairness_in_renting', 'DC Fairness in Renting: application fee cap, disclosures and eviction records', 'fees', '{"eviction":{"lookbackYearsMax":3,"excludeDismissed":true},"fees":{"capType":"cpi","cap":54,"refundIfNotScreened":true,"refundDays":14},"process":{"criteriaDisclosureBeforeFee":true,"writtenDenialRequired":true}}'::jsonb, '2022-05-18', null, 'active', 'warn', 'D.C. Code §42-3505.10', 'https://code.dccouncil.gov/us/dc/council/code/sections/42-3505.10', null, 'verified', '2026-11-08', 'The $50 base is CPI-adjusted each year; the Office of the Tenant Advocate gives $54 for 2026: update yearly. No other fee before lease signing, no holding deposit from voucher holders, and no adverse action on credit score alone. Eviction cases that didn''t end in a judgment for the landlord, or were filed 3 or more years ago, may not be considered. Some subsections are noted as not yet implemented.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://code.dccouncil.gov/us/dc/council/code/sections/42-3505.10","https://ota.dc.gov/node/1815961"],"quotes":["Such an application fee will be no more than $50.","shall refund any application fee paid by the prospective tenant within a reasonable time, not to exceed 14 days.","Was filed 3 or more years ago","$54 for Calendar Year 2026"],"capSource":"DC Office of the Tenant Advocate, 2026","capYear":2026}'::jsonb),
  ('e799f4b4-3fe4-5a44-80c2-08e489237785', 'US-TX', 'state', null, 'tx_tenant_selection_criteria_notice', 'Texas notice of tenant selection criteria with the application', 'process', '{"notices":{"extraContent":["signed_acknowledgment","tenant_selection_criteria"]}}'::jsonb, '2008-01-01', null, 'active', 'warn', 'Tex. Prop. Code §92.3515', 'https://texas.public.law/statutes/tex._prop._code_section_92.3515', null, 'verified', '2026-11-08', 'Criteria (criminal history, rental history, current income, credit history, false or incomplete information) are given with the application; an unsigned acknowledgment presumes they weren''t. Rejecting without the notice means refunding the fee and deposit. Read on the texas.public.law mirror (the official site is a script-only app).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://texas.public.law/statutes/tex._prop._code_section_92.3515"],"quotes":["the landlord shall make available to the applicant printed notice of the landlord''s tenant selection criteria","the landlord shall return the application fee and any application deposit."]}'::jsonb),
  ('f1184a37-511f-52d2-9b4d-ef1647f9d80b', 'US-CA', 'state', null, 'ca_unlawful_detainer_record_masking', 'California masking of eviction (unlawful detainer) court records', 'eviction', '{}'::jsonb, null, null, 'active', 'warn', 'Cal. Code Civ. Proc. §1161.2', 'https://california.public.law/codes/code_of_civil_procedure_section_1161.2', null, 'verified', '2026-11-08', 'Limits who can see eviction court records rather than what a landlord may weigh: cases stay masked unless the landlord won within 60 days (or after trial by court order); pandemic-period rent cases stay masked. Reference only. Read on the california.public.law mirror.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://california.public.law/codes/code_of_civil_procedure_section_1161.2"],"quotes":["The clerk shall allow access to limited civil case records filed under this chapter, ... only as follows:","to any other person 60 days after the complaint has been filed ... if judgment against all defendants has been entered for the plaintiff within 60 days"]}'::jsonb),
  ('4cd12451-479b-5184-b0c9-940316d0dd73', 'US-CA', 'state', null, 'ca_covid_rental_debt_screening', 'California: COVID-19 rental debt not a negative screening factor', 'credit', '{}'::jsonb, null, null, 'active', 'warn', 'Cal. Civ. Code §1785.20.4', 'https://california.public.law/codes/civil_code_section_1785.20.4', null, 'verified', '2026-11-08', 'Rent that came due between Mar 1, 2020 and Sep 30, 2021 may not count against an applicant. The definition borrows from CCP §1179.02, whose chapter repealed itself on Oct 1, 2025; how that affects this section is unresolved, so treat it as in force and ask counsel. Reference only (no field captures it).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://california.public.law/codes/civil_code_section_1785.20.4","https://codes.findlaw.com/ca/civil-code/civ-sect-1785-20-4/"],"quotes":["shall not use an alleged COVID-19 rental debt ... as a negative factor for the purpose of evaluating a prospective housing application ... or as the basis for refusing to rent a dwelling unit to an otherwise qualified prospective tenant."]}'::jsonb),
  ('4b7c0980-ed43-56d6-a24f-3e6d6522afcf', 'US-CA-OAKLAND', 'city', 'Oakland', 'oakland_fair_chance_housing', 'Oakland Fair Chance Access to Housing Ordinance', 'criminal', '{"criminal":{"allowed":false,"mustAttachDocs":true},"preOfferInquiryBanned":["criminal"],"process":{"writtenDenialRequired":true}}'::jsonb, '2020-02-04', null, 'active', 'warn', 'Oakland Mun. Code ch. 8.25 (Ord. 13581 C.M.S.)', 'https://www.oaklandca.gov/resources/fair-chance-access-to-housing-ordinance', null, 'verified', '2026-11-08', 'Bars asking about or using criminal history (arrests, convictions, sealed and juvenile records included). Narrow exceptions: the California lifetime sex-offender registry, checked only after a conditional rental agreement and stated on the application; screening federal or state law requires, with notice and consent. Exempt: owner-occupied single-family homes, properties of up to three units with the owner in one, owner move-back units, and replacement or added co-tenants. Landlords must show the City''s notice on applications. Adopted text read from a scan hosted by the East Bay Rental Housing Association (the code host returned 403).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://assets-002.noviams.com/novi-file-uploads/ebrha/pdfs-and-documents/ordinance_no__13581_c_m_s__o_m_c__8_25-cc6d7722.pdf","https://www.oaklandca.gov/resources/fair-chance-access-to-housing-ordinance"],"quotes":["shall not, at any time or by any means, whether direct or indirect, inquire about an Applicant''s Criminal History","base an Adverse Action in whole or in part on an Applicant''s Criminal History","a copy of any Criminal History, Background Check Report ... and an opportunity to respond with rebutting or mitigating information prior to the denial"]}'::jsonb),
  ('987025c9-59df-5aa4-8e70-29ee63d7c068', 'US-CA-BERKELEY', 'city', 'Berkeley', 'berkeley_fair_chance_housing', 'Berkeley Ronald V. Dellums Fair Chance Access to Housing Ordinance', 'criminal', '{"criminal":{"allowed":false,"mustAttachDocs":true},"preOfferInquiryBanned":["criminal"],"process":{"writtenDenialRequired":true}}'::jsonb, null, null, 'active', 'warn', 'Berkeley Mun. Code ch. 13.106 (Ord. 7,692-N.S.; Ord. 7,733-N.S.)', 'https://rentboard.berkeleyca.gov/sites/default/files/documents/Fair%20Chance%20Notice%20to%20Rental%20Property%20Owners.pdf', null, 'checked', '2026-11-08', 'Bars asking about or basing decisions on criminal history, with the same registry and federal or state exceptions as Oakland (registry only after a conditional rental agreement). Exempt: owner-occupied properties of one to three units, owner move-back units, tenants adding roommates. Read from the Rent Board''s notice and FAQ and Ord. 7,733; the code host returned 403, so re-check the code text. Effective date varies by source (March–April 2020).', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://rentboard.berkeleyca.gov/sites/default/files/documents/Fair%20Chance%20Notice%20to%20Rental%20Property%20Owners.pdf","https://rentboard.berkeleyca.gov/sites/default/files/documents/Fair%20Chance%20FAQ%20for%20Rental%20Property%20Owners%20and%20Managers.pdf","https://berkeleyca.gov/sites/default/files/documents/2020-10-13%20Item%2001%20Ordinance%207733.pdf"],"quotes":["Inquiring about Criminal History","A copy of the Criminal History report, background check, or other information received that is the basis of the decision"]}'::jsonb),
  ('7267d902-c3c9-5697-b56d-6e796ff22778', 'US-CA', 'state', null, 'ca_feha_criminal_history_regulations', 'California FEHA regulations on criminal history in housing', 'criminal', '{"criminal":{"excluded":["arrests_without_conviction","dismissed","diversion","juvenile","pardoned","sealed_expunged"]}}'::jsonb, '2020-01-01', null, 'active', 'warn', 'Cal. Code Regs. tit. 2, §§12264–12271', 'https://www.law.cornell.edu/regulations/california/2-CCR-12269', null, 'verified', '2026-11-08', 'Only directly-related convictions may be considered, and blanket bans are unlawful. Individualized assessment and a chance to give mitigating information are factors in the less-discriminatory-alternative test rather than standalone duties, so they aren''t encoded. No inquiry ban and no fixed look-back. Federal or state mandates are a defense; stricter local laws apply. Read on the Cornell LII mirror.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.law.cornell.edu/regulations/california/2-CCR-12269","https://www.law.cornell.edu/regulations/california/2-CCR-12266","https://www.law.cornell.edu/regulations/california/2-CCR-12270"],"quotes":["Seek, consider, use, or take an adverse action based on criminal history information about any arrest","any criminal conviction that has been sealed, dismissed, vacated, expunged, voided, invalidated, pardoned,","a matter considered in or processed through the juvenile justice system"]}'::jsonb),
  ('cf964fa1-0a82-56ee-b768-537f73f7ca17', 'US-WA-SEATTLE', 'city', 'Seattle', 'seattle_fair_chance_housing', 'Seattle Fair Chance Housing Ordinance', 'criminal', '{"criminal":{"allowed":false},"process":{"writtenDenialRequired":true}}'::jsonb, '2018-02-19', null, 'active', 'warn', 'Seattle Mun. Code ch. 14.09; Yim v. City of Seattle, 63 F.4th 783 (9th Cir. 2023)', 'https://www.seattle.gov/civilrights/civil-rights/fair-housing/fair-chance-housing', null, 'checked', '2026-11-08', 'After Yim v. City of Seattle (9th Cir. 2023) the City no longer enforces the ban on asking about criminal history (since June 6, 2023), so asking isn''t barred; requiring disclosure, and adverse action on criminal history, still are. Exception: sex-offender registry information about adult convictions, with a legitimate business reason and a written denial naming the registry information. Exempt: owner-occupied single-family homes, ADUs with the owner on the lot, and federally assisted housing where federal rules require denial. Read from the Office for Civil Rights'' page and FAQ; the code host returned 403.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.seattle.gov/civilrights/civil-rights/fair-housing/fair-chance-housing","https://www.seattle.gov/documents/Departments/CivilRights/Enforcement/Fair%20Housing/FairChanceHousing/Fair-Chance-Housing-FAQ-June-6-2023.pdf"],"quotes":["The landlord is prohibited from requiring disclosure, rejecting an applicant, or taking an adverse action based on any arrest record, conviction record, or criminal history, except for registry information"]}'::jsonb),
  ('b3dc2093-b115-5350-bb39-556cd8e73055', 'US-WA-SEATTLE', 'city', 'Seattle', 'seattle_first_in_time', 'Seattle first-in-time rule and screening-criteria notice', 'process', '{"process":{"firstInTime":true}}'::jsonb, '2017-01-01', null, 'active', 'warn', 'Seattle Mun. Code §14.08.050; Yim v. City of Seattle (Wash. 2019)', 'https://seattle.gov/civilrights/civil-rights/fair-housing/first-in-time', null, 'checked', '2026-11-08', 'Offer the unit to the first qualified applicant with a complete application; give the criteria (minimum thresholds, documents needed, how to ask for more time) before collecting information; at least 72 hours to supply documents and 48 hours to accept. Doesn''t apply to ADUs or a dwelling the owner lives in; set-aside units must be disclosed. Upheld by the Washington Supreme Court (Nov 14, 2019). Read from the Office for Civil Rights'' page and FAQ.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://seattle.gov/civilrights/civil-rights/fair-housing/first-in-time","https://www.seattle.gov/documents/Departments/CivilRights/Enforcement/Fair%20Housing/FAQ_FIT_11-20-19.pdf"],"quotes":["offer tenancy to the first qualified applicant who provides a completed application"]}'::jsonb),
  ('ce36eaa4-caeb-55a5-a727-6bc8c23a5b8e', 'US-OR-PORTLAND', 'city', 'Portland', 'portland_fair_screening', 'Portland FAIR application screening', 'income', '{"income":{"maxMultiple":2.5,"tenantPortionForVoucher":true},"process":{"firstInTime":true,"writtenDenialRequired":true}}'::jsonb, '2025-01-01', null, 'active', 'warn', 'Portland City Code 30.01.086', 'https://www.portland.gov/code/30/01/086', null, 'verified', '2026-11-08', 'The income cap depends on the rent: up to 2.5× when the rent is below the Housing Bureau''s published maximum rent for households at 80% of median family income, and 2× at or above it. The 2.5× upper bound is encoded; at or above that rent the limit is 2×, which the warning doesn''t catch. Criteria stricter than the low-barrier set need an individual assessment. Applications are decided in order of receipt, in writing within two weeks with a 30-day appeal. Screening fees are limited to the screening company''s charge (D.7). Exemptions include units shared with the owner, owner-occupied duplexes and ADUs, and referral-only regulated affordable housing. Current text effective Jan 1, 2025.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.portland.gov/code/30/01/086"],"quotes":["up to but not greater than 2.5 times the amount of the rent for the dwelling unit","up to, but not greater than two times the amount of the rent for the dwelling unit","Calculate based on a rental amount that is reduced by the amount of any local, state, or federal government rent voucher","must accept, conditionally accept, or deny applicants in order of receipt."]}'::jsonb),
  ('7213938a-92f5-5c0d-b884-af71c47826ee', 'US-OR-PORTLAND', 'city', 'Portland', 'portland_fair_low_barrier_criteria', 'Portland FAIR low-barrier screening criteria (optional)', 'criminal', '{}'::jsonb, '2025-01-01', null, 'active', 'warn', 'Portland City Code 30.01.086.E', 'https://www.portland.gov/code/30/01/086', null, 'verified', '2026-11-08', 'Optional: landlords who adopt these criteria agree not to reject for misdemeanors sentenced over 3 years ago, felonies over 7 years ago, arrests without a pending charge, eviction judgments 3 or more years old, a credit score of 500 or more, or debts under $1,000. Landlords using stricter criteria must do an individual assessment instead. Reference only, so it sets no value.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://www.portland.gov/code/30/01/086"],"quotes":["A criminal conviction for misdemeanor offenses for which the dates of sentencing are older than three years","a felony offense for which the dates of sentencing are older than seven years"]}'::jsonb),
  ('785ea551-0f6b-5904-9566-5f5cbc3b1965', 'US-OR', 'state', null, 'or_applicant_criminal_eviction_history', 'Oregon limits on criminal and eviction history in screening', 'criminal', '{"criminal":{"excluded":["arrests_without_charges","decriminalized","marijuana_use_possession"]},"eviction":{"lookbackYearsMax":5,"excludeDismissed":true}}'::jsonb, null, null, 'active', 'warn', 'ORS 90.303', 'https://oregon.public.law/statutes/ors_90.303', null, 'verified', '2026-11-08', 'Arrests count only when they led to charges that are pending (and not in diversion or deferral); convictions only for conduct still illegal in Oregon and in the listed categories. Eviction judgments five or more years old, dismissed actions and pandemic-window (Apr 2020–Mar 2022) nonpayment judgments may not be considered. Read on the oregon.public.law mirror (2023 edition plus 2024 session; oregonlegislature.gov refused the connection): confirm 2025 changes.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://oregon.public.law/statutes/ors_90.303"],"quotes":["a landlord may consider a previous arrest of the applicant only if the arrest resulted in charges","but not including convictions based solely on the use or possession of marijuana","Entered five or more years before the applicant submits the application"]}'::jsonb),
  ('87e55c6f-900e-5ab4-bd67-57f7027bffac', 'US-OR', 'state', null, 'or_applicant_screening_charge', 'Oregon applicant screening charge', 'fees', '{"fees":{"capType":"actual_cost","actualCostLimit":true,"receiptRequired":true,"refundIfNotScreened":true,"refundDays":30,"noFeeIfNoUnit":true},"process":{"criteriaDisclosureBeforeFee":true}}'::jsonb, null, null, 'active', 'warn', 'ORS 90.295', 'https://oregon.public.law/statutes/ors_90.295', null, 'verified', '2026-11-08', 'The charge may not exceed the landlord''s average actual cost or the customary amount charged by screening companies. Before charging, the landlord must have written criteria and give notice of the charge, criteria and process. One charge per 60 days per applicant. Read on the oregon.public.law mirror; re-check for 2025 session changes.', '{"reviewEvery":"quarter","reviewDue":"2027-02-08","read":["https://oregon.public.law/statutes/ors_90.295"],"quotes":["must not be greater than the landlord''s average actual cost","The landlord must provide the applicant with a receipt for any applicant screening charge.","when the landlord knows or should know that no rental units are available at that time","must refund the applicant screening charge to the applicant within 30 days if the landlord:"]}'::jsonb)
