-- Screening rules (RISK-05): the shared catalog of location-specific tenant-screening rules
--
-- Generated from the 2026-11-08 screening-law research run: each row was read against its primary text (or the official
-- mirror named in metadata.read) and carries its citation, source link, verification and the date checked. Reference
-- content, not legal advice; enforcement is warn. Re-verify quarterly (metadata.reviewDue). Re-runnable: rows upsert on
-- their stable id (derived from jurisdiction_code + rule_key).

on conflict (id) do update set
  jurisdiction_code = excluded.jurisdiction_code,
  scope = excluded.scope,
  locality = excluded.locality,
  rule_key = excluded.rule_key,
  title = excluded.title,
  topic = excluded.topic,
  effects = excluded.effects,
  effective_from = excluded.effective_from,
  effective_to = excluded.effective_to,
  status = excluded.status,
  enforcement = excluded.enforcement,
  citation = excluded.citation,
  source_url = excluded.source_url,
  legal_resource_id = excluded.legal_resource_id,
  verification = excluded.verification,
  verified_on = excluded.verified_on,
  notes = excluded.notes,
  metadata = excluded.metadata,
  deleted_at = null;
